ype=\"https://schema.org/AggregateRating\">\n    <span itemprop=\"ratingValue\">{rating}</span>★ (<span itemprop=\"reviewCount\">{review_count}</span>)\n  </div>\n</main>", "profile": [{"kind": "header", "name": "{business_name}", "subtitle": "Specialized Hospital · {credential_line}", "initials": "{initials}", "badges": ["Verified"], "rating": "{rating}", "ratingCount": "{review_count}", "chips": ["{location_chip}"], "bio": "{bio}", "ctas": ["{primary_cta}", "{secondary_cta}"]}, {"kind": "infoCards", "cards": [{"title": "Contact", "lines": ["{phone}", "{city}, {state}", "{website}"], "chips": ["{social_chips}"]}, {"title": "Credentials", "lines": ["{license_line}", "{memberships_line}"], "chips": ["{designation_chips}"]}]}, {"kind": "lines", "title": "About", "lines": ["{about_line_1}", "{about_line_2}"]}, {"kind": "roster", "title": "Professionals", "members": [{"initials": "{m_initials}", "name": "{m_name}", "meta": "{m_meta}"}], "note": "Roster ranked by search rank score."}, {"kind": "stats", "title": "Track record", "stats": [{"value": "{stat1}", "label": "{stat1_label}"}, {"value": "{stat2}", "label": "{stat2_label}"}]}, {"kind": "services", "title": "Products & services", "items": ["{service_items}"]}, {"kind": "chips", "title": "Specialties", "chips": ["Organ Transplantation Program", "Cardiothoracic Surgery Program", "Comprehensive Oncology Program", "Pediatric Specialty Care Program", "Neonatal Intensive Care Unit", "Neurosurgery and Neurology Program", "Trauma and Emergency Surgery", "Rehabilitation Medicine Program"]}, {"kind": "score", "title": "Search rank score", "value": 0, "max": 850}, {"kind": "reviews", "title": "Reviews", "sources": ["Experience.com", "Google"], "reviews": [{"author": "{reviewer}", "loc": "{city}", "rating": "{review_rating}", "date": "{review_date}", "body": "{review_text}"}]}, {"kind": "disclaimer", "text": "{compliance_disclaimer}"}]}]}$pj$::jsonb,'registry-projection-linted-v1',now())
